def _mask_card_numbers(data) -> dict:
    """Return a copy of the event payload with any `card_number` field masked, leaving all other
    fields (including nested ones) unchanged. The mask matches the shop's standard card display."""
    def walk(node):
        if isinstance(node, dict):
            return {
                key: (mask_card_number(value) if key == "card_number" else walk(value))
                for key, value in node.items()
            }
        if isinstance(node, list):
            return [walk(item) for item in node]
        return node

    return walk(data)
